import { boatProduct, boatCategoryOverrides } from "./boat";
import { storeProducts, newProductIds } from "./store-products";

export { syncedAt } from "./store-products";

export const products = storeProducts.reduce((result, product) => {
  result[product.id] = product;
  return result;
}, { TJ_601: boatProduct });

// New products follow the store homepage widget, including its displayed order.
export const categories = {
  newProducts: newProductIds.map(id => ({ id: 'naver_' + id })).filter(entry => products[entry.id]),
  allProducts: [
    { id: 'TJ_601', overrides: boatCategoryOverrides.allProducts },
    ...storeProducts.map(product => ({ id: product.id })),
  ],
};

export function getHomeProducts() {
  return Object.keys(categories).reduce((result, name) => {
    result[name] = categories[name].map(({ id, overrides }) => ({ ...products[id], ...overrides }));
    return result;
  }, {});
}

// Keep the surviving legacy detail URL connected to its current store product.
const legacyStoreIds = { SH100100: "naver_5613466212" };
export function getStoreProduct(modelName) {
  if (typeof modelName !== "string") return null;
  const id = Object.prototype.hasOwnProperty.call(legacyStoreIds, modelName) ? legacyStoreIds[modelName] : modelName;
  return Object.prototype.hasOwnProperty.call(products, id) && products[id].storeId ? products[id] : null;
}
