import Vue from "vue"
import VueRouter from "vue-router"
import Home from "../views/Home.vue"

Vue.use(VueRouter)

const routes = [
  {
    path: "/",
    name: "Home",
    component: Home,
    props: (route) => ({
      modelName: typeof route.query.modelName === "string" ? route.query.modelName : ""
    })
  },
  {
    path: "/detail",
    name: "Detail",
    component: () => import(/* webpackChunkName: "product-detail" */ "../views/Detail.vue"),
    props: (route) => ({
      modelName: typeof route.query.modelName === "string" ? route.query.modelName : ""
    })
  }
]

const router = new VueRouter({
  mode: "history",
  base: process.env.BASE_URL,
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    }
    else {
      return { x: 0, y: 0 }
    }
  }
})

// A static host's 404 page returns visitors to the root before restoring the URL.
router.beforeEach((to, from, next) => {
  if (to.path === "/" && typeof to.query.__route === "string") {
    const requested = to.query.__route;
    if (/^\/detail(?:[?#]|$)/.test(requested)) {
      const { route } = router.resolve(requested);
      next({ path: route.path, query: route.query, hash: route.hash, replace: true });
    } else {
      next({ path: "/", replace: true });
    }
    return;
  }
  next();
});

export default router
